using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Web.Script.Serialization;
public static class WeaponRuntime {
 sealed class Origin {public int pid;public string ticks;public long pointer,original;public string baseline,appliedHash;}
 sealed class Journal {
  public string file;public List<Origin> entries=new List<Origin>();
  public Journal(string state){file=Path.Combine(state,"weapon-origins.json");try{entries=ModIO.Read<List<Origin>>(file);}catch{}}
  static string Hash(byte[] bytes){using(var h=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(h.ComputeHash(bytes));}
  public void Record(Mem m,long copy,long original,byte[] baseline){string ticks=ProcessIdentity.StartTicks(m.Process);var found=entries.FirstOrDefault(x=>x.pid==m.Process.Id&&x.ticks==ticks&&x.pointer==copy);if(found==null){found=new Origin{pid=m.Process.Id,ticks=ticks,pointer=copy,original=original,baseline=Convert.ToBase64String(baseline)};entries.Add(found);}found.appliedHash=Hash(m.R(copy,GunSwayPlan.Size));if(entries.Count>256)throw new Exception("当前对局的私有参数记录较多，请重启客户端后继续");ModIO.Put(file,entries,true);}
  public void Recover(WeaponSdk.Patch patch){if(patch==null)return;string ticks=ProcessIdentity.StartTicks(patch.M.Process);var known=entries.Where(x=>x.pid==patch.M.Process.Id&&x.ticks==ticks).ToList();var origin=known.FirstOrDefault(x=>x.pointer==patch.Data);if(origin==null)return;var baseline=Convert.FromBase64String(origin.baseline);if(baseline.Length!=GunSwayPlan.Size||patch.M.Q(origin.original)!=BitConverter.ToInt64(baseline,0)||Hash(patch.M.R(origin.pointer,GunSwayPlan.Size))!=origin.appliedHash)throw new Exception("旧私有参数已变化，等待重新部署角色");patch.Data=origin.original;patch.Baseline=baseline;patch.Adopt(known.Where(x=>x.original==origin.original&&x.baseline==origin.baseline).Select(x=>x.pointer));}
 }
 static bool Same(WeaponSdk.Patch a,WeaponSdk.Patch b){return a!=null&&b!=null&&a.Weapon==b.Weapon&&a.Sway==b.Sway&&a.Firing==b.Firing&&a.Context==b.Context&&a.Soldier==b.Soldier;}
 static void Clear(ref WeaponSdk.Patch patch){if(patch!=null){patch.Restore();patch=null;}}
 static void RestoreAll(ref WeaponSdk.Patch clientPatch,ref WeaponSdk.Patch serverPatch,BallisticsDriver ballistics,string state){try{Clear(ref clientPatch);}catch(Exception e){ModIO.Event(state,"client-restore-error",e.ToString());}try{Clear(ref serverPatch);}catch(Exception e){ModIO.Event(state,"server-restore-error",e.ToString());}try{if(ballistics!=null)ballistics.Clear();}catch(Exception e){ModIO.Event(state,"ballistics-restore-error",e.ToString());}}
 static void Update(ref WeaponSdk.Patch active,WeaponSdk.Patch next,bool recoil,bool spread,Journal journal){if(active!=null&&!Same(active,next))Clear(ref active);if(next==null)return;if(active==null){journal.Recover(next);if(next.Baseline==null)next.Baseline=next.M.R(next.Data,GunSwayPlan.Size);active=next;}active.Apply(recoil,spread);}
 static string Name(Mem client,Roster roster){long now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();if(roster==null||!roster.Fresh(now))return "";long context=client.Q(client.Base+0x2670d80),manager=client.Q(context+0x60),local=client.Q(manager+0x540);string name=client.S(local+0x40,64);return roster.players.Any(p=>p.name==name&&!String.IsNullOrEmpty(p.guid))?name:"";}
 public static int Main(string[] args){if(args.Length==1&&args[0]=="--self-test"){try{var bytes=new byte[GunSwayPlan.Size];for(int i=0;i<bytes.Length;i+=4)Array.Copy(BitConverter.GetBytes(1f),0,bytes,i,4);var onlySpread=GunSwayPlan.Create(bytes,false,true);if(GunSwayPlan.Recoil.Any(o=>BitConverter.ToSingle(onlySpread,o)!=1f)||GunSwayPlan.Spread.Intersect(GunSwayPlan.Recoil).Any())return 1;return 0;}catch{return 1;}}
  if(args.Length!=2||args[0]!="--input")return 2;string inputFile=Path.GetFullPath(args[1]),token=null,stateDirectory=Path.GetDirectoryName(inputFile),lastError="";Mem client=null,server=null;Process cp=null,sp=null;WeaponSdk.Patch clientPatch=null,serverPatch=null;BallisticsDriver ballistics=null;Journal journal=new Journal(stateDirectory);long lastStatus=0,lastDiagnostic=0;FeatureInput input=null;string phase="read-input";
  try{for(;;){try{
   phase="read-input";input=ModIO.Read<FeatureInput>(inputFile);long now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();if(input==null||!input.enabled||now-input.at>5000)break;if(token==null)token=input.instanceId;if(token!=input.instanceId)break;
   phase="verify-instance";string host=Path.Combine(Path.GetFullPath(input.launcherRoot),"host");if(input.client==null||input.server==null)throw new Exception("等待本实例服务端和客户端");
   if(cp!=null&&(cp.HasExited||cp.Id!=input.client.pid||sp.HasExited||sp.Id!=input.server.pid))throw new Exception("实例进程已结束");
   if(client==null){cp=Process.GetProcessById(input.client.pid);sp=Process.GetProcessById(input.server.pid);ProcessIdentity.Verify(cp,Path.Combine(host,"mods/client/bf4_no_drm.exe"),input.client.startTicks);ProcessIdentity.Verify(sp,Path.Combine(host,"runtime/GameServer/bf4_Server_Final.exe"),input.server.startTicks);client=new Mem(cp,null,true);server=new Mem(sp,"160ec988aad0632946936a21a9aed1c73f5b906161f2d96b2a085ee65ce183ba",true);ballistics=new BallisticsDriver(client);WeaponSdk.RecordClone=journal.Record;}
   phase="resolve-player";string name=Name(client,input.roster);long cs=name.Length>0?WeaponSdk.Client(client,name):0,ss=name.Length>0?WeaponSdk.Server(server,name):0;bool alive=cs!=0&&ss!=0;
   bool recoil=Values.Flag(input.config,"noRecoil",false),spread=Values.Flag(input.config,"noSpread",false),drop=Values.Flag(input.config,"noBulletDrop",false),fast=Values.Flag(input.config,"fastBullets",false);
   phase="apply-weapon";Update(ref clientPatch,alive&&(recoil||spread)?WeaponSdk.Find(client,name):null,recoil,spread,journal);Update(ref serverPatch,alive&&spread?WeaponSdk.FindServer(server,ss):null,false,spread,journal);bool bullet=ballistics.Set(alive?cs:0,drop,fast);
   bool clientOk=clientPatch!=null&&clientPatch.IsApplied(recoil,spread),serverOk=serverPatch!=null&&serverPatch.IsApplied(false,true);bool applied=alive&&(!recoil||clientOk)&&(!spread||(clientOk&&serverOk))&&(!(drop||fast)||bullet);
   string message=!alive?"等待本机步兵部署":applied?"枪械参数已回读确认":"等待当前武器确认参数";
   if(now-lastStatus>=400){lastStatus=now;var status=new{apiVersion=1,clientBuild=Mem.ClientBuild,instanceId=token,at=now,pid=Process.GetCurrentProcess().Id,state=applied?"applied":"waiting",message=message,phase=phase,clientPid=input.client.pid,serverPid=input.server.pid,noRecoil=recoil&&clientOk,noSpread=spread&&clientOk&&serverOk,noBulletDrop=drop&&bullet,fastBullets=fast&&bullet,clientConfirmed=clientOk,serverConfirmed=serverOk};ModIO.Put(input.statusFile,status);if(now-lastDiagnostic>3000){lastDiagnostic=now;ModIO.Event(stateDirectory,"weapon-readback",status);}}
   lastError="";
  }catch(Exception error){long now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();if(error.ToString()!=lastError||now-lastDiagnostic>3000){lastError=error.ToString();lastDiagnostic=now;ModIO.Event(stateDirectory,"weapon-error",new{phase=phase,error=error.ToString()});}if(input!=null)ModIO.Put(input.statusFile,new{instanceId=token,at=now,pid=Process.GetCurrentProcess().Id,state="error",message=error.Message,phase=phase});RestoreAll(ref clientPatch,ref serverPatch,ballistics,stateDirectory);if(client!=null)client.Dispose();if(server!=null)server.Dispose();client=server=null;ballistics=null;if(cp!=null)cp.Dispose();if(sp!=null)sp.Dispose();cp=sp=null;Thread.Sleep(500);}
  Thread.Sleep(40);
  }}finally{RestoreAll(ref clientPatch,ref serverPatch,ballistics,stateDirectory);if(client!=null)client.Dispose();if(server!=null)server.Dispose();if(cp!=null)cp.Dispose();if(sp!=null)sp.Dispose();}
  return 0;
 }
}
